// ─── File: MetaspaceDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.metaspace;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MetaspaceDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        MetaspaceReporter reporter = new MetaspaceReporter();
        reporter.report("startup");

        // Simulate repeated "redeploys": each iteration uses a NEW class loader,
        // loads classes, then DROPS the loader (no reference kept = reclaimable).
        for (int deploy = 1; deploy <= 5; deploy++) {
            loadWithThrowawayLoader(deploy);
        }
        // Encourage reclamation of unreachable class loaders' metadata.
        System.gc();
        Thread.sleep(200);
        reporter.report("after 5 redeploys + GC (loaders released)");

        log.info(() -> "Metaspace reclaims a loader's class metadata once the loader is unreachable");
    }

    // Each call creates a short-lived class loader; dropping it makes the
    // loaded class metadata eligible for Metaspace reclamation (unlike PermGen leaks).
    private static void loadWithThrowawayLoader(int deploy) throws Exception {
        ClassLoader loader = new java.net.URLClassLoader(new java.net.URL[0],
                MetaspaceDemo.class.getClassLoader());
        // Load a core class through this loader to exercise metadata.
        Class<?> c = Class.forName("java.util.ArrayList", true, loader);
        log.fine(() -> "deploy " + deploy + " loaded " + c.getName() + " via throwaway loader");
        // 'loader' goes out of scope here → eligible for collection → metadata reclaimable.
    }
}

// ─── Would be in MetaspaceReporter.java (reads the Metaspace memory pool) ───
class MetaspaceReporter {
    private static final Logger log = Logger.getLogger("BankLog");

    void report(String phase) {
        for (java.lang.management.MemoryPoolMXBean pool :
                java.lang.management.ManagementFactory.getMemoryPoolMXBeans()) {
            if (pool.getName().contains("Metaspace")) {
                long usedKb = pool.getUsage().getUsed() / 1024;
                log.info(() -> "[" + phase + "] Metaspace used = " + usedKb + " KB"
                        + " (native memory, auto-grows unless MaxMetaspaceSize set)");
            }
        }
    }
}
